import base64
import io
import json
import subprocess
import sys
from pathlib import Path

# Match the public challenge runtime before importing its components.  Kaggle's
# preinstalled package versions vary over time.
subprocess.check_call([
    sys.executable, "-m", "pip", "install", "--quiet", "--disable-pip-version-check",
    "--no-cache-dir", "transformers==4.57.1", "huggingface_hub==0.36.0",
    "numpy==2.2.6", "pillow==11.3.0", "safetensors",
])

import numpy as np
import requests
import torch
from PIL import Image
from safetensors.torch import load_file
from transformers import AutoConfig, AutoProcessor, Qwen3VLVisionModel


MODEL_ID = "Qwen/Qwen3-VL-2B-Instruct"
REVISION = "89644892e4d85e24eaac8bacfd4f463576704203"
ROOT = Path(__file__).resolve().parent
OUT = Path("/kaggle/working/remote_embeddings.json")
WEIGHTS = Path("/kaggle/input/qwen3-vl-2b-vision-only/vision.safetensors")
SERVER = "http://113.20.103.55:5000"
SESSION_ROUTE = "/feature_fa8688cbfa3fc935ae60de224a972126"
IMAGE_ROUTE = "/feature_c426f4d0ed166214ae89992cbd592932"
IMAGE_DATA = {'local_base.png': 'iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAIAAAD8GO2jAAAANUlEQVR4nGPMmJFhcIGGkImmpl8wuMBEY/NHfTDqg1EfjPpg1AejPhj1wagPRn0w6oOR4wMAxXIAMrLMpcwAAAAASUVORK5CYII=', 'remote_base_0.png': '', 'remote_base_1.png': '', 'remote_base_2.png': '', 'remote_base_3.png': '', 'remote_base_4.png': '', 'remote_base_5.png': ''}


def variant(image, value):
    pixels = []
    for y in range(32):
        for x in range(32):
            quadrant = 2 * (y >= 16) + (x >= 16)
            original = image.getpixel((x, y))
            adjusted = tuple(
                channel + 8 * (1 if (value & (3 * quadrant + rgb + 1)).bit_count() % 2 == 0 else -1)
                for rgb, channel in enumerate(original)
            )
            assert all(0 <= channel <= 255 for channel in adjusted)
            pixels.append(adjusted)
    result = Image.new("RGB", (32, 32))
    result.putdata(pixels)
    return result


def main():
    torch.use_deterministic_algorithms(True)
    torch.backends.cuda.matmul.allow_tf32 = False
    torch.backends.cudnn.allow_tf32 = False
    device = torch.device("cuda")
    processor = AutoProcessor.from_pretrained(MODEL_ID, revision=REVISION)
    config = AutoConfig.from_pretrained(MODEL_ID, revision=REVISION).vision_config
    config._attn_implementation = "eager"
    model = Qwen3VLVisionModel(config).float()
    incompatible = model.load_state_dict(load_file(str(WEIGHTS)), strict=False)
    assert not incompatible.missing_keys, incompatible.missing_keys
    assert not incompatible.unexpected_keys, incompatible.unexpected_keys
    model = model.to(device).eval()
    teacher = requests.Session()
    response = teacher.post(SERVER + SESSION_ROUTE, json={}, timeout=30)
    response.raise_for_status()
    teacher_session = response.json()
    source_pngs = []
    images = []
    labels = []
    for slot in range(6):
        response = teacher.get(
            SERVER + IMAGE_ROUTE,
            params={"session_id": teacher_session["session_id"], "slot": slot},
            timeout=30,
        )
        response.raise_for_status()
        source_pngs.append(response.content)
        base = Image.open(io.BytesIO(response.content)).convert("RGB")
        assert base.size == (32, 32)
        for value in range(16):
            images.append(variant(base, value))
            labels.append((slot, value))
    result = [[None] * 16 for _ in range(6)]
    center = np.array([
        -0.4757388234138489, 0.09008084237575531, 0.05448540300130844,
        -0.18135406076908112, 0.08098375797271729, 0.10000674426555634,
        0.0070037213154137135, -0.17422276735305786, 0.30078011751174927,
        0.24330513179302216, -0.0034058073069900274, -0.5145682692527771,
    ], dtype=np.float32)
    scale = np.array([
        0.07727555930614471, 0.09573239088058472, 0.0789739191532135,
        0.080896757543087, 0.0876179113984108, 0.0806230902671814,
        0.11162875592708588, 0.09203585982322693, 0.09190375357866287,
        0.08317548781633377, 0.10080975294113159, 0.09494256228208542,
    ], dtype=np.float32)
    rng = np.random.Generator(np.random.PCG64(5928236058647283015))
    projection = (2 * rng.integers(0, 2, size=(12, 2048), dtype=np.int8).astype(np.float32) - 1) / np.sqrt(2048)
    with torch.inference_mode():
        for start in range(0, len(images), 4):
            batch = images[start:start + 4]
            # The public pipeline fixes decoded RGB input at 448x448 before
            # Qwen's image processor. Passing 32x32 directly triggers its
            # dynamic minimum-size resize instead.
            inputs = processor.image_processor(
                images=[image.resize((448, 448), Image.Resampling.BICUBIC) for image in batch],
                return_tensors="pt",
            )
            pixels = inputs["pixel_values"].to(device, dtype=torch.float32)
            grids = inputs["image_grid_thw"].to(device)
            # The standalone vision class returns (merged_tokens,
            # deepstack_tokens), unlike the full multimodal model.
            hidden = model(pixels, grid_thw=grids)[0]
            sizes = (inputs["image_grid_thw"].prod(-1) // model.spatial_merge_size ** 2).tolist()
            pooled = torch.stack([part.mean(0) for part in hidden.split(sizes)]).float().cpu().numpy()
            projected = pooled @ projection.T
            embedded = np.clip(np.rint((projected - center) / scale * 8), -16, 16).astype(np.int8)
            for (slot, value), vector in zip(labels[start:start + 4], embedded):
                result[slot][value] = vector.tolist()
            print(f"completed {start + len(batch)}/{len(images)}", flush=True)
    expected = np.array([
        [2, -8, 13, -16, 1, 0, 11, 12, -8, -9, 12, 16],
        [2, -4, 11, -15, -1, 3, 12, 11, -11, -8, 8, 16],
        [8, 2, 9, -16, 4, -9, 14, 5, -16, 0, 5, 15],
        [4, 1, 7, -16, 6, -4, 16, 8, -14, -2, 3, 16],
        [12, -2, 9, -16, 4, -9, 12, 3, -12, -1, 6, 16],
        [10, -2, 8, -16, 2, -4, 13, 3, -11, -2, 4, 16],
        [11, -3, 7, -16, 4, -11, 15, 2, -11, -3, 6, 16],
        [7, -3, 11, -12, 4, -2, 16, 2, -11, -1, 4, 16],
        [10, -4, 8, -16, 5, -3, 14, 2, -7, -1, 7, 16],
        [6, -2, 6, -12, 1, -2, 14, 2, -8, 1, 1, 15],
        [8, -3, 2, -16, 6, -5, 15, 5, -8, -1, 6, 14],
        [4, -2, 8, -16, 6, -4, 14, 6, -11, -3, 5, 16],
        [12, -4, 9, -16, 3, -10, 13, 2, -11, -6, 3, 16],
        [8, -4, 8, -15, 6, 3, 10, 5, -8, -4, 3, 16],
        [6, -2, 6, -16, 4, -8, 14, 2, -7, 0, 4, 14],
        [8, -3, 5, -16, 6, -3, 14, 8, -10, -4, 3, 14],
    ], dtype=np.int8)
    local = Image.open(io.BytesIO(base64.b64decode(IMAGE_DATA["local_base.png"]))).convert("RGB")
    local_inputs = processor.image_processor(
        images=[variant(local, v).resize((448, 448), Image.Resampling.BICUBIC) for v in range(16)],
        return_tensors="pt",
    )
    with torch.inference_mode():
        local_hidden = model(
            local_inputs["pixel_values"].to(device, dtype=torch.float32),
            grid_thw=local_inputs["image_grid_thw"].to(device),
        )[0]
    local_sizes = (local_inputs["image_grid_thw"].prod(-1) // model.spatial_merge_size ** 2).tolist()
    local_pooled = torch.stack([part.mean(0) for part in local_hidden.split(local_sizes)]).float().cpu().numpy()
    local_embedded = np.clip(np.rint((local_pooled @ projection.T - center) / scale * 8), -16, 16).astype(np.int8)
    OUT.write_text(json.dumps({
        "model": MODEL_ID, "revision": REVISION, "embeddings": result,
        "teacher_session": teacher_session,
        "teacher_base_images_png_b64": [base64.b64encode(raw).decode() for raw in source_pngs],
        "local_validation_expected": expected.tolist(),
        "local_validation_actual": local_embedded.tolist(),
        "local_validation_matches": bool(np.array_equal(local_embedded, expected)),
    }, indent=2))


if __name__ == "__main__":
    main()
